package rules; import core.*;import java.util.HashSet;import java.util.List;import java.util.Set; public final class RuleValidator{public Diagnostics validate(List<IdsRule> rules){Diagnostics d=new Diagnostics();Set<String>sids=new HashSet<>();if(rules==null)return d;int idx=0;for(IdsRule r:rules){idx++;if(!r.action().matches("alert|pass|drop|reject|log"))d.medium("rule.action","unexpected action at rule "+idx);if(!r.protocol().matches("ip|tcp|udp|icmp|http|dns|tls"))d.low("rule.protocol","unusual protocol at rule "+idx);if(r.sid().isBlank())d.medium("rule.sid","missing sid at rule "+idx);else if(!sids.add(r.sid()))d.high("rule.sid.duplicate","duplicate sid "+r.sid());if(r.msg().isBlank())d.low("rule.msg","missing msg at rule "+idx);if(r.options().containsKey("content")&&r.options().get("content").isEmpty())d.medium("rule.content","empty content at rule "+idx);}return d;}}
